int list_get(const IntList *l, int i, int *out)
{
    if (i < 0 || i >= l->len) return 0;   /* cap is room, not items */
    *out = l->data[i];
    return 1;
}

void list_free(IntList *l)
{
    my_free(l->data);
    l->data = NULL;            /* empty again, safe to free twice */
    l->len = 0;
    l->cap = 0;
}

