typedef struct {
    int *data;   /* the items, on the heap */
    int len;     /* how many are in use */
    int cap;     /* how many fit before we must grow */
} IntList;

void list_init(IntList *l)
{
    l->data = NULL;
    l->len = 0;
    l->cap = 0;
}

int list_push(IntList *l, int value)
{
    if (l->len == l->cap) {
        int new_cap = l->cap ? l->cap * 2 : 4;
        int *tmp = my_realloc(l->data, new_cap * sizeof *tmp);
        if (tmp == NULL) return 0;        /* l->data is still valid */
        l->data = tmp;
        l->cap = new_cap;
    }
    l->data[l->len++] = value;
    return 1;
}

int list_filter(IntList *l, int lo, int hi)
{
    int w = 0;                                  /* where the next kept value goes */
    for (int r = 0; r < l->len; r++)
        if (l->data[r] >= lo && l->data[r] <= hi)
            l->data[w++] = l->data[r];
    int removed = l->len - w;
    l->len = w;
    return removed;
}
